pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, bytes memory data, uint256 sendValue, uint256 initialBalance, uint256 withdrawAmount) public {
        // Bound fuzz parameters to reasonable ranges
        initialBalance = bound(initialBalance, 0, 100 ether);
        sendValue = bound(sendValue, 0, 10 ether);
        withdrawAmount = bound(withdrawAmount, 0, 10 ether);

        // Setup: fund contract and caller
        vm.deal(address(c), initialBalance);
        vm.deal(address(this), 20 ether);

        // Record pre-state
        uint256 preBalance = address(c).balance;

        // Execute Command with potential withdraw
        c.Command{value: sendValue}(target, data);

        // Record post-state
        uint256 postBalance = address(c).balance;

        // The rule: after Command, the contract balance should be preBalance + sendValue (if no revert)
        // If Command reverted, we wouldn't reach here, so the rule is simply:
        assertTrue(postBalance == preBalance + sendValue, "Balance should increase by sent value");
    }
}

