    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, bytes memory data, uint256 sendVal, uint256 initBalance) public {
        // Ensure caller is Owner
        vm.assume(caller == c.Owner());
        // Bound initBalance and sendVal to reasonable values
        initBalance = bound(initBalance, 1, 1e18);
        sendVal = bound(sendVal, 0, 1e18);
        // Give the contract initial balance
        vm.deal(address(c), initBalance);
        // Call Command with msg.value = sendVal
        vm.prank(caller);
        c.Command{value: sendVal}(address(0), data);
        // Now call withdraw
        vm.prank(caller);
        c.withdraw();
        // Assert: contract balance should be zero
        assertTrue(address(c).balance == 0);
    }
}

