pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, uint256 value, uint256 seed) public {
        vm.assume(adr != address(c));
        vm.assume(adr != address(0));
        // Ensure the contract has initial balance
        vm.deal(address(c), 1 ether);
        // Ensure msg.value >= address(this).balance for multiplicate
        uint256 contractBal = address(c).balance;
        vm.assume(value >= contractBal);
        // Call multiplicate from a non-owner to trigger bug path
        vm.prank(address(0xdead));
        (bool okMulti, ) = address(c).call{value: value}(abi.encodeWithSignature("multiplicate(address)", adr));
        if (!okMulti) return; // skip if multiplicate reverts

        // Now Owner calls withdraw
        address owner = c.Owner();
        uint256 balBefore = address(c).balance;
        vm.prank(owner);
        (bool okWithdraw, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        if (okWithdraw) {
            uint256 balAfter = address(c).balance;
            assertTrue(balAfter == 0, "Withdraw should empty contract balance");
        }
    }
}

