pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address adr, uint256 initialBalance, uint256 extraValue) public {
        // Bound inputs to reasonable ranges
        vm.assume(owner != address(0));
        vm.assume(adr != address(0) && adr != address(c));
        vm.assume(adr != owner);
        vm.assume(initialBalance <= 1e24);
        vm.assume(extraValue <= 1e24);
        vm.assume(extraValue >= initialBalance); // ensure msg.value >= address(this).balance

        // Set owner as the caller
        vm.prank(owner);

        // Fund the contract with initialBalance
        vm.deal(address(c), initialBalance);

        // Record contract balance before the operation
        uint256 balanceBefore = address(c).balance;

        // Calculate the expected transfer amount for the correct version
        // In correct version: payable(adr).transfer(address(this).balance + msg.value)
        uint256 expectedTransfer = balanceBefore + extraValue;

        // Record adr balance before
        uint256 adrBalanceBefore = adr.balance;

        // Call multiplicate via Command to avoid direct call
        bytes memory data = abi.encodeWithSignature("multiplicate(address)", adr);
        c.Command{value: extraValue}(address(c), data);

        // After the call, for the correct version: contract balance becomes 0, adr receives expectedTransfer
        uint256 actualAdrBalance = adr.balance;
        uint256 contractBalanceAfter = address(c).balance;

        // The rule: the amount transferred to adr must be exactly expectedTransfer (balanceBefore + extraValue)
        // This means adr's balance increased by expectedTransfer and contract balance is 0
        bool rule = (actualAdrBalance - adrBalanceBefore == expectedTransfer) && (contractBalanceAfter == 0);
        assertTrue(rule);
    }
}

