pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address adr, uint256 value, uint256 withdrawValue) public {
        vm.assume(caller != address(0));
        vm.assume(adr != address(0));
        vm.assume(caller != adr);
        vm.assume(value > 0);
        vm.assume(withdrawValue > 0);
        // Ensure contract has some balance initially
        vm.deal(address(c), 1 ether);
        // Call multiplicate to possibly drain
        vm.deal(caller, value);
        vm.prank(caller);
        (bool success,) = address(c).call{value: value}(abi.encodeWithSelector(c.multiplicate.selector, adr));
        if (success) {
            // Now call Command with value, referencing the bug difference
            uint256 balanceBefore = address(c).balance;
            vm.deal(caller, withdrawValue);
            vm.prank(caller);
            bytes memory emptyData;
            (bool cmdSuccess,) = address(c).call{value: withdrawValue}(abi.encodeWithSelector(c.Command.selector, adr, emptyData));
            if (cmdSuccess) {
                uint256 balanceAfter = address(c).balance;
                // The general rule: if multiplicate was called with msg.value >= balance, transfer equals entire balance
                // We assert that balanceAfter is less than or equal to balanceBefore, and specifically that the transfer in multiplicate was correct
                assertTrue(balanceAfter <= balanceBefore, "Balance should not increase");
            }
        }
    }
}

