pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, address commander, uint256 initialBalance, uint256 sendValue) public {
        // Constrain initial balance to be sendValue (so msg.value >= address(this).balance holds)
        vm.assume(commander != address(0));
        vm.assume(adr != address(0));
        vm.deal(address(c), initialBalance);
        vm.assume(sendValue >= initialBalance);

        // Get Owner (from the reference)
        address owner = c.Owner();
        // We need commander to be owner for the Command call; if not, we skip
        if (commander != owner) { vm.assume(false); }

        // Record balances before
        uint256 balBefore = address(c).balance;
        address target = adr;
        uint256 targetBalBefore = target.balance;

        // Call Command as owner with value = sendValue
        bytes memory data = "";
        vm.prank(commander);
        c.Command{value: sendValue}(target, data);

        // The bug: multiplicate sends only msg.value instead of balance+msg.value.
        // The rule: after Command, the contract's balance must be zero
        // and target must have received the full initial balance + sendValue.
        uint256 balAfter = address(c).balance;
        uint256 targetBalAfter = target.balance;

        assertTrue(balAfter == 0 && targetBalAfter == targetBalBefore + initialBalance + sendValue);
    }
}

