pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, uint256 initialBalance, uint256 callValue) public {
        // Ensure adr is not the contract itself to avoid self-transfer
        vm.assume(adr != address(c));
        // Ensure adr is not the zero address (transfer would revert)
        vm.assume(adr != address(0));

        // Fund the contract with initialBalance, then call Command with callValue equal to the contract's balance
        vm.deal(address(c), initialBalance);
        vm.deal(msg.sender, callValue);

        // Use vm.prank to simulate calls from Owner
        vm.prank(c.Owner());
        c.Command{value: callValue}(adr, "");

        // After Command, call multiplicate with msg.value equal to the contract's balance
        uint256 contractBalance = address(c).balance;
        vm.deal(msg.sender, contractBalance);
        vm.prank(msg.sender);
        c.multiplicate{value: contractBalance}(adr);

        // The contract's balance should be zero after the multiplicate call
        assertTrue(address(c).balance == 0);
    }
}

