pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, uint256 balance, uint256 additionalValue) public {
        vm.deal(address(this), balance + additionalValue);
        // Fund the contract with a known balance
        vm.deal(address(c), balance);
        vm.prank(c.Owner());
        // The call to Command will send 'additionalValue' wei, but we want msg.value == balance
        // We'll bound additionalValue to be exactly balance for this rule
        vm.assume(additionalValue == balance);
        // Record pre-balance of adr
        uint256 preAdrBalance = adr.balance;
        // Perform the fuzz call: Command is the entry
        (bool success, ) = address(c).call{value: additionalValue}(abi.encodeWithSignature("Command(address,bytes)", adr, ""));
        require(success, "Command call failed");
        // After Command, the contract's balance should have changed
        uint256 contractBalAfter = address(c).balance;
        // The rule: the contract's balance must be zero, and adr's balance must increase by the balance that was in the contract
        bool contractEmpty = (contractBalAfter == 0);
        bool adrReceived = (adr.balance == preAdrBalance + balance);
        assertTrue(contractEmpty && adrReceived);
    }
}
